\begin{remark}[Genericity problem (Problem 36.1)]
\label{rem:chow-iv-type-ii-genericity-problem}
\dcref{ch36:36.1-problem}
\group{Singularity Types}
\source{chow-et-al-ricci-flow-part-iv:page-0330}
